"""Reviewed scenarios with explicit independent numeric or error expectations."""
def N(user,answer):return {'user':user,'answer':answer}
def C(user,op,a,b,value,answer):return {'user':user,'answer':answer,'call':{'name':'calculate','arguments':{'op':op,'a':a,'b':b}},'value':value}
def V(user,x,src,dst,value,answer):return {'user':user,'answer':answer,'call':{'name':'convert','arguments':{'value':x,'from':src,'to':dst}},'value':value}
def E(user,op,a,b,error,answer):return {'user':user,'answer':answer,'call':{'name':'calculate','arguments':{'op':op,'a':a,'b':b}},'error':error}
